const crypto = require('crypto');
const secret = $env.LENDLOOP_SHARED_SECRET;
if (!secret) throw new Error('LENDLOOP_SHARED_SECRET is not set');
const sign = (ts, body) => crypto.createHmac('sha256', secret).update(`${ts}.${body}`).digest('hex');

// Report the failed execution to Convex so it shows up in the admin view.
const e = $input.first().json;
const body = JSON.stringify({
  executionId: e.execution?.id ?? `trigger-${Date.now()}`,
  workflow: e.workflow?.name ?? 'unknown',
  node: e.execution?.lastNodeExecuted ?? e.trigger?.node?.name ?? 'unknown',
  message: String(e.execution?.error?.message ?? e.trigger?.error?.message ?? 'unknown error').slice(0, 200),
});
console.error('[LendLoop automation error]', body);
const ts = String(Date.now());
return [{ json: { body, ts, sig: sign(ts, body) } }];
